pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Ensure arrays are non-empty and have matching lengths
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // Ensure the call does not revert due to mismatched array lengths (already handled)
        // We call the function and check the return value directly
        bool result = c.transfer(from, caddress, _tos, v);
        assertTrue(result);
    }
}
